        message: '请输入时间',
        trigger: 'manual'
      }],
      num: [{
        required: true,
        message: '请输入数量',
        trigger: 'manual'
      }],
      velocity: [{
        required: true,
        message: '请输入速度',
        trigger: 'manual'
      }]
    };

    // 使用父组件暴露的 fetchContainers 和 containers 数据
    const {
      fetchContainers,
      containers
    } = DockerContainers;
    onMounted(() => {
      fetchContainers(); // 获取容器列表
    });
    const openDialog = () => {
      dialogVisible.value = true;
      fetchContainers(); // 每次打开时获取容器列表
